package com.example.adbtoolbox.common

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

object AppSettings {
    var isDarkMode by mutableStateOf(true)
    var language by mutableStateOf("zh") // "zh" or "en" or "hi"
    var navIndicatorStyle by mutableStateOf("capsule") // "capsule"=capsule shape, "round"=round shape
    var shizukuAutoActivate by mutableStateOf(false) // Shizuku auto activate

    // 主题 id，见 com.example.adbtoolbox.common.theme.AppTheme
    // "classic" / "national_day" / "huawei"
    var themeId by mutableStateOf("classic")
    // 用户是否手动选过主题。false = 从未选过，国庆档期首次启动会自动套用国庆主题
    var themeChosenByUser by mutableStateOf(false)

    // 首次设置向导是否已完成。false = 首次启动要先走向导（欢迎 → 主题 → 权限 → 完成）。
    // 落盘键 app_onboarding_done；用户点"跳过"也算完成，不会反复弹。
    var onboardingDone by mutableStateOf(false)

    // 开屏动画开关（v2.9+，落盘键 app_splash_anim）。
    // 关闭后进入软件将不再播放开屏视频，直接进主界面。
    var splashAnimEnabled by mutableStateOf(true)
    // UI 风格：false=液态玻璃（默认），true=安卓原生/Google 混合扁平风
    var nativeUi by mutableStateOf(false)

    /**
     * 用户在"液态玻璃调节"里手动改过玻璃参数。
     *
     * 为什么必须有这个标记：主题只负责"一套推荐参数"，而玻璃参数本身允许用户覆盖。
     * 如果只靠"存档值是否等于主题值"来判断，一旦存档与主题不一致，主题就会被判丢——
     * 表现正是"主题明明选中了（首页横幅还在），玻璃颜色与高光却回到了原来那套"。
     * 有了这个标记，规则变成确定的：
     *   选过主题 + 没手动改过 → 每次启动都以主题为准；
     *   手动改过 → 以用户改的为准（主题不再强行覆盖）。
     */
    var themeUserOverrode by mutableStateOf(false)

    /** 标记"用户手动调整过玻璃参数"。所有玻璃调节入口都应调用它。 */
    fun markThemeUserOverride() {
        themeUserOverrode = true
    }

    fun toggleDarkMode() {
        isDarkMode = !isDarkMode
    }

    fun toggleNavIndicatorStyle() {
        navIndicatorStyle = if (navIndicatorStyle == "capsule") "round" else "capsule"
    }

    fun getNavIndicatorHeight(): Float {
        return if (navIndicatorStyle == "capsule") 50f else 56f
    }
}

// Simple multi-language text mapping (zh/en/hi)
object AppStrings {
    fun get(key: String): String {
        return when (AppSettings.language) {
            "en" -> enStrings[key] ?: key
            "hi" -> hiStrings[key] ?: (enStrings[key] ?: key)
            else -> zhStrings[key] ?: key
        }
    }

