        "hw_group_net" to "网络与待机",
        "hw_group_sys" to "系统级（深度）",
        "hw_m_bg_kill_all" to "结束全部后台进程",
        "hw_m_bg_kill_all_principle" to "调用 ActivityManagerService.killAllBackgroundProcesses，只结束 cached 状态的后台进程，前台应用与本应用不受影响；比逐个 force-stop 更干净。",
        "hw_m_bg_kill_all_gain" to "立即回收缓存进程占用的内存，减少内存压力导致的应用重载。",
        "hw_m_bg_disable_ota" to "停用系统更新服务",
        "hw_m_bg_disable_ota_principle" to "com.huawei.android.hwouc 负责 OTA 检查、下载与包校验，会周期性联网唤醒。停用后不再检查更新，升级入口同时失效（可用恢复命令重新启用）。",
        "hw_m_bg_disable_ota_gain" to "去掉周期性联网与升级包校验的 CPU、网络与存储开销。",
        "hw_m_bg_disable_stats" to "停用华为数据统计上报",
        "hw_m_bg_disable_stats_principle" to "com.huawei.bd 承担用户体验改进计划的数据采集与回传，随系统常驻，持续产生日志写入与网络上报。不同 ROM 上该包名与职责可能略有差异，请用验证命令确认本机是否存在。",
        "hw_m_bg_disable_stats_gain" to "减少后台日志写入与上报唤醒，不影响系统功能。",
        "hw_m_bg_autostart_page" to "打开华为应用启动管理",
        "hw_m_bg_autostart_page_principle" to "自启由手机管家（HwSystemManager）统一接管，没有公开的 shell 写入接口。本方法只用 am start 拉起\"应用启动管理\"页面，由用户手动关闭自启，不做任何隐藏改动。",
        "hw_m_bg_autostart_page_gain" to "在华为机型上，手动关闭自启是减少后台唤醒最有效的手段。",
        "hw_m_mem_trim_caches" to "清理全部应用缓存",
        "hw_m_mem_trim_caches_principle" to "pm trim-caches 让 PackageManager 通知每个应用把自身缓存裁剪到指定空闲空间，应用各自清理自己的 cache 目录，不会删除应用数据。",
        "hw_m_mem_trim_caches_gain" to "释放存储空间，并减少缓存占用带来的存储带宽与内存压力。",
        "hw_m_mem_drop_caches" to "回收内核页缓存",
        "hw_m_mem_drop_caches_principle" to "写 3 到 /proc/sys/vm/drop_caches 让内核丢弃 pagecache、dentries 与 inodes；写入前必须先 sync，否则脏页会先被写回造成额外 I/O。",
        "hw_m_mem_drop_caches_gain" to "立刻把被文件缓存占用的内存还给系统，降低内存压力。",
        "hw_m_mem_compact_memory" to "触发内存碎片整理",
        "hw_m_mem_compact_memory_principle" to "写 1 到 /proc/sys/vm/compact_memory，让内核立刻做一次内存规整，把可迁移页合并为连续块。",
        "hw_m_mem_compact_memory_gain" to "提高后续大块内存分配的命中率，降低长时间运行后的分配延迟抖动。",
        "hw_m_mem_lmk_tune" to "调整低内存回收阈值",
        "hw_m_mem_lmk_tune_principle" to "改写 /sys/module/lowmemorykiller/parameters/minfree（单位为 4KB 页）。本方法把阈值调到较低水平，让系统尽量保留后台进程；原值写入 /data/local/tmp/hw_lmk_backup 供恢复。Android 11 以后多数机型改用用户态 lmkd，该节点可能不存在。",
        "hw_m_mem_lmk_tune_gain" to "后台应用保留更多，切回时减少冷启动重载；阈值过低会加剧内存回收抖动。",
        "hw_m_mem_zram_off" to "关闭 ZRAM 交换",
        "hw_m_mem_zram_off_principle" to "swapoff /dev/block/zram0 停用内存压缩交换，CPU 不再花时间做页压缩与解压。",
        "hw_m_mem_zram_off_gain" to "仅当物理内存充足、卡顿来自交换抖动时才有收益；内存不足的机型关闭后会明显变慢。",
        "hw_m_gpu_anim_scale" to "动画时长缩到 0.5x",
        "hw_m_gpu_anim_scale_principle" to "改写 window_animation_scale、transition_animation_scale、animator_duration_scale 三个全局设置，WindowManager 与 Choreographer 按比例缩短动画时长。",
        "hw_m_gpu_anim_scale_gain" to "界面切换等待时间减半，主观响应更快；不改变真实帧率。",
        "hw_m_gpu_skiagl" to "强制 HWUI 使用 SkiaGL",
        "hw_m_gpu_skiagl_principle" to "debug.hwui.renderer=skiagl 让 HWUI 走 Skia 的 GPU 后端。Android 12 之后默认已是 SkiaGL，只有在 EMUI 10/11（Android 10/11）默认走 OpenGL 时才有实际差别。",
        "hw_m_gpu_skiagl_gain" to "在默认走 OpenGL 的老版本 EMUI 上可减少渲染管线切换开销。",
        "hw_m_gpu_render_scale" to "降低渲染分辨率",
        "hw_m_gpu_render_scale_principle" to "用 wm size 把逻辑分辨率设为物理分辨率的 85%（按 4 的倍数取整），SurfaceFlinger 再缩放输出，GPU 每帧要填充的像素减少约 28%。目标值在运行时按真实物理分辨率现算，不写死。",
        "hw_m_gpu_render_scale_gain" to "明显降低 GPU 负载与功耗，代价是画面变软、个别应用布局异常。",
        "hw_m_gpu_sf_latch" to "允许非同步帧提交",
        "hw_m_gpu_sf_latch_principle" to "debug.sf.latch_unsignaled=1 关闭 SurfaceFlinger 对 frame buffer 的同步等待，缩短一帧的流水延迟。",
        "hw_m_gpu_sf_latch_gain" to "降低触控到显示的延迟；个别应用可能出现撕裂。",
        "hw_m_power_mode_on" to "打开华为性能模式",
        "hw_m_power_mode_on_principle" to "向 Settings.Global / Secure 写入 hw_power_mode=1 与 hw_performance_mode=1，触发华为功耗管理切到性能档。键名在不同 EMUI / HarmonyOS 版本上并不统一，务必先用\"验证本机可用性\"确认。",
        "hw_m_power_mode_on_gain" to "放开 CPU / GPU 频率与调度限制，重负载下掉帧减少。",
        "hw_m_power_saver_off" to "退出省电模式",
        "hw_m_power_saver_off_principle" to "把 Settings.Global 的 low_power 与 low_power_sticky 置 0，PowerManagerService 随即退出省电模式。",
        "hw_m_power_saver_off_gain" to "解除省电模式对 CPU 频率、后台同步与亮度策略的限制。",
        "hw_m_power_fixed_perf" to "固定高性能模式",
        "hw_m_power_fixed_perf_principle" to "cmd power set-fixed-performance-mode-enabled true 让 PowerManagerService 在亮屏期间维持固定性能档，不再动态降频。该子命令需要 Android 11 及以上。",
        "hw_m_power_fixed_perf_gain" to "重负载下频率稳定，减少降频造成的卡顿；发热与耗电明显增加。",
        "hw_m_power_gov_performance" to "CPU 调频切 performance",
        "hw_m_power_gov_performance_principle" to "把每个核心的 /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor 写为 performance，跳过调频采样直接锁最高频。原值先备份到 /data/local/tmp/hw_gov_backup，恢复命令按备份逐核还原。",
        "hw_m_power_gov_performance_gain" to "频率响应最快，满载性能最高；空载也维持高频，耗电与发热显著上升。",
        "hw_m_power_thermal_off" to "关闭内核温控",
        "hw_m_power_thermal_off_principle" to "把 /sys/class/thermal/thermal_zone*/mode 写为 disabled，停用内核温控降频；原值备份到 /data/local/tmp/hw_thermal_backup。华为自有的温控服务可能绕过该节点，实际是否生效必须以验证输出为准。",
        "hw_m_power_thermal_off_gain" to "高温时不再降频，短时满载性能更高；存在真实的过热与硬件损伤风险。",
        "hw_m_storage_bg_dexopt" to "立即执行后台 dexopt",
        "hw_m_storage_bg_dexopt_principle" to "cmd package bg-dexopt-job 让 PackageManager 立刻执行一次后台 dexopt，按 baseline / profile 把应用编译为机器码，不必等系统在夜间空闲时自行调度。",
        "hw_m_storage_bg_dexopt_gain" to "应用冷启动与首帧更快；执行期间 CPU 占用高，耗时随已安装应用数量增长。",
        "hw_m_storage_compile_all" to "全量 speed-profile 编译",
        "hw_m_storage_compile_all_principle" to "cmd package compile -m speed-profile -a 对所有已安装应用做 profile 引导的 AOT 编译，结果写入各自 oat 文件；恢复命令 --reset 清除编译产物，回到解释执行加 JIT。",
        "hw_m_storage_compile_all_gain" to "启动速度提升最明显的一条；耗时可能超过十分钟，并额外占用存储。",
        "hw_m_storage_fstrim" to "手动 TRIM /data",
        "hw_m_storage_fstrim_principle" to "fstrim -v /data 把已删除数据块的回收请求下发给闪存控制器，缓解长期使用后的写入放大。",
        "hw_m_storage_fstrim_gain" to "恢复擦除块的写入性能；命令本身较慢，实际整理由主控在后台完成。",
        "hw_m_storage_clear_logs" to "清理崩溃日志与 logcat",
        "hw_m_storage_clear_logs_principle" to "删除 /data/tombstones、/data/system/dropbox、/data/anr 下的历史日志并清空 logcat 缓冲区，减少日志写入 I/O。",
        "hw_m_storage_clear_logs_gain" to "回收存储并减少日志写入；代价是丢失崩溃现场，出问题时无法回溯。不可逆。",
        "hw_m_net_wifi_scan_off" to "关闭始终扫描 WLAN",
        "hw_m_net_wifi_scan_off_principle" to "wifi_scan_always_enabled=0 关闭系统在 WLAN 关闭状态下仍持续扫描的开关，减少待机唤醒与射频占用。",
        "hw_m_net_wifi_scan_off_gain" to "降低待机唤醒次数与耗电；依赖扫描的位置定位精度会下降。",
        "hw_m_net_mobile_always_on_off" to "关闭始终开启移动数据",
        "hw_m_net_mobile_always_on_off_principle" to "mobile_data_always_on=0 关闭\"始终开启移动数据\"，避免连接 WLAN 时仍维持移动数据链路。",
        "hw_m_net_mobile_always_on_off_gain" to "减少移动数据链路维持带来的耗电与信令开销。",
        "hw_m_net_wifi_low_latency" to "开启 WLAN 低延迟模式",
        "hw_m_net_wifi_low_latency_principle" to "cmd wifi force-low-latency-mode enabled 让 WLAN 驱动停止省电轮询，保持低延迟收发。需要 Android 11 及以上，并且驱动实现支持该子命令。",
        "hw_m_net_wifi_low_latency_gain" to "降低游戏与实时通信的网络抖动；耗电略增。",
        "hw_m_net_tcp_rwnd" to "提高 TCP 初始接收窗口",
        "hw_m_net_tcp_rwnd_principle" to "net.tcp.default_init_rwnd 是 Android 网络栈读取的初始接收窗口值（以 MSS 倍数计），系统默认 10，本方法设为 60。该属性默认为内核内置值，未显式设置时 getprop 读到空串。",
        "hw_m_net_tcp_rwnd_gain" to "高延迟链路上更快达到可用带宽；弱网或短连接场景收益有限。",
        "hw_m_sys_disable_hwaps" to "停用华为应用加速服务",
        "hw_m_sys_disable_hwaps_principle" to "com.huawei.android.hwaps 是华为的应用加速 / 预加载服务，会预测用户行为并提前加载应用。停用后不再做预加载，后台 I/O 与内存占用下降。该服务在不同 ROM 上职责不完全一致，可能同时影响冷启动表现。",
        "hw_m_sys_disable_hwaps_gain" to "减少后台 I/O 与常驻内存；是否更快取决于机型和 ROM，行为不确定。",
        "hw_m_sys_disable_push" to "停用华为推送服务",
        "hw_m_sys_disable_push_principle" to "com.huawei.android.pushagent 负责华为推送通道的长连接与消息分发。停用后系统不再维持该长连接，所有依赖华为推送的应用都收不到离线消息。",
        "hw_m_sys_disable_push_gain" to "减少一条常驻长连接的唤醒、内存与耗电；代价是所有华为推送通知都会丢失。",
        "hw_m_sys_io_scheduler" to "块设备调度器切 none",
        "hw_m_sys_io_scheduler_principle" to "把 /sys/block/*/queue/scheduler 写为 none，去掉调度层重排队开销；UFS / NVMe 多队列设备通常本就使用 none。原值先备份到 /data/local/tmp/hw_io_backup。",
        "hw_m_sys_io_scheduler_gain" to "降低随机 I/O 延迟；部分内核不支持 none，写入会被忽略（看状态回读）。",
        "hw_m_sys_readahead" to "提高块设备预读",
        "hw_m_sys_readahead_principle" to "把 /sys/block/*/queue/read_ahead_kb 设为 2048，顺序读取时一次预取更多数据；原值先备份到 /data/local/tmp/hw_ra_backup。",
        "hw_m_sys_readahead_gain" to "大文件顺序读更快；随机读为主时收益有限，预读过多会挤占页缓存。",
        "temp_root_title" to "临时 Root 提权",
        "temp_root_cpu_hint" to "请选择与您的处理器型号匹配的提权包，不同机型的提权方法不同。",
        "temp_root_vendor" to "厂商",
        "temp_root_soc_mediatek" to "联发科（天玑）",
        "temp_root_soc_qualcomm" to "高通（骁龙）",
        "temp_root_package" to "提权包",
        "temp_root_selected" to "已选择：%1\$s",
        "temp_root_pick_zip" to "选择提权包（ZIP）",
        "temp_root_perm_hint" to "提权包需要以 shell/Root 身份执行脚本，当前未检测到 Shizuku(ADB) 或 Root 权限，执行大概率会失败。",
        "temp_root_flash" to "执行提权",
        "temp_root_warn" to "提权操作有风险，可能导致设备无法启动。请先备份重要数据。",
        "temp_root_start" to "开始提权",
        "temp_root_running" to "正在提权…",
        "temp_root_fail_no_file" to "提权失败：未选择提权包",
        "temp_root_fail_exception" to "提权失败：执行异常，请确认 Shizuku/Root 权限后重试",
        "temp_root_ok" to "提权成功！\n%1\$s",
        "temp_root_fail" to "提权失败：%1\$s\n%2\$s",
        "installed_root_modules" to "已装 Root 模块",
        "close" to "关闭",
        "size" to "大小",
        "copy" to "复制",
        "perf_item_bg_kill_background_all" to "结束全部后台进程",
        "perf_item_bg_kill_background_all_desc" to "am kill-all 结束所有可回收的后台进程并回读 Free RAM；检测到 Shizuku 或 Root 时可用",
        "perf_item_bg_trim_all_caches" to "清理全部应用缓存",
        "perf_item_bg_trim_all_caches_desc" to "pm trim-caches 释放所有应用缓存占用，并回读 /data 剩余空间",
        "perf_item_bg_standby_bucket_rare" to "常用应用移入 RARE 待机分组",
        "perf_item_bg_standby_bucket_rare_desc" to "对 15 个常见第三方应用执行 am set-standby-bucket rare，减少后台唤醒；会明显延迟这些应用的通知，可恢复为 active",
        "perf_item_bg_standby_bucket_extreme" to "重点应用移入 RESTRICTED 分组",
        "perf_item_bg_standby_bucket_extreme_desc" to "对微信、淘宝、抖音等 5 个应用执行 am set-standby-bucket restricted，后台几乎完全冻结；消息推送会严重延迟甚至丢失，可恢复。此接口在部分 ROM 上被裁剪，默认不勾选",
        "perf_item_bg_restrict_background_appops" to "限制第三方应用后台运行",
        "perf_item_bg_restrict_background_appops_desc" to "对前 60 个第三方应用设置 appops RUN_IN_BACKGROUND / RUN_ANY_IN_BACKGROUND deny，真正切断后台驻留；这些应用的通知可能延迟，可用恢复命令还原为 allow",
        "perf_item_bg_deviceidle_whitelist_core" to "核心系统组件加入 Doze 白名单",
        "perf_item_bg_deviceidle_whitelist_core_desc" to "把 SystemUI / 电话 / 蓝牙 / 电话信息 Provider 加入 deviceidle 白名单，避免被 Doze 冻结造成卡顿；执行后回读白名单首行",
        "perf_item_bg_deviceidle_unforce" to "立即退出 Doze 待机",
        "perf_item_bg_deviceidle_unforce_desc" to "cmd deviceidle unforce 让系统立刻离开 IDLE 状态并回读 mState，唤醒被冻结的后台任务。不可逆项（不是设置，是一次性动作）",
        "perf_item_bg_deviceidle_disable" to "关闭 Doze 深度待机",
        "perf_item_bg_deviceidle_disable_desc" to "cmd deviceidle disable 关闭 Doze 深度休眠，后台不再被冻结；会显著增加待机耗电，且 Android 12 以后该子命令在部分 ROM 上已移除，默认不勾选",
        "perf_item_bg_oom_adj_policy" to "调整 OOM 杀进程策略",
        "perf_item_bg_oom_adj_policy_desc" to "写入 /proc/sys/vm/oom_kill_allocating_task=0 与 oom_dump_tasks=1，让 OOM 时优先清理占用内存最多的进程并记录现场，需要 Root；执行后回读两个节点",
        "perf_item_cpu_fixed_perf_mode" to "开启固定性能模式",
        "perf_item_cpu_fixed_perf_mode_desc" to "cmd power set-fixed-performance-mode-enabled true 让 CPU/GPU 长期维持高频；发热与耗电明显增加，执行后回读 mFixedPerformanceMode",
        "perf_item_cpu_governor_performance" to "CPU 调度器改为 performance",
        "perf_item_cpu_governor_performance_desc" to "逐核写入 scaling_governor=performance，写入前把原调度器备份到 /data/local/tmp 并提供恢复；恢复命令可从备份逐项还原，需要 Root。回读 cpu0 当前调度器",
        "perf_item_cpu_min_freq_boost" to "抬高 CPU 最低频率到最高频",
        "perf_item_cpu_min_freq_boost_desc" to "把 scaling_min_freq 写成 cpuinfo_max_freq，压缩降频空间；写入前逐核备份原值，可恢复，需要 Root。回读 cpu0 的 min/max 频率",
        "perf_item_cpu_schedutil_rate_limit" to "降低调频采样间隔",
        "perf_item_cpu_schedutil_rate_limit_desc" to "把 rate_limit_us 压到 2000，让频率响应更快；写入前备份原值可恢复，需要 Root。不同内核该节点路径可能不同，先看回读值",
        "perf_item_cpu_io_scheduler_none" to "块设备 IO 调度器改为 none",
        "perf_item_cpu_io_scheduler_none_desc" to "对 sd*/mmcblk*/dm-*/vda 写入调度器 none，减少闪存上的排队开销；写入前记录原调度器并可恢复，需要 Root。该路径主要适用于 UFS/eMMC 设备",
        "perf_item_mem_swappiness_low" to "降低内存交换倾向",
        "perf_item_mem_swappiness_low_desc" to "写入 vm.swappiness=10 与 page-cluster=150，减少内存页在 ZRAM 里的换入换出开销；原 swappiness 备份后可恢复，需要 Root。执行后回读两个节点",
        "perf_item_power_perf_profile" to "取消系统省电模式档位",
        "perf_item_power_perf_profile_desc" to "cmd power set-mode 0 把电源档位退出省电模式并回读状态；set-profile 子命令在部分 ROM 上不存在时会如实报错，不影响前面已生效的部分",
        "perf_item_storage_bg_dexopt_now" to "立即执行后台 Dex 优化",
        "perf_item_storage_bg_dexopt_now_desc" to "cmd package bg-dexopt-job 立即对未优化应用做 AOT 编译，加快应用启动；耗时可达数分钟，执行期间发热属正常",
        "perf_item_storage_compile_speed_profile" to "全量 speed-profile 编译",
        "perf_item_storage_compile_speed_profile_desc" to "cmd package compile -m speed-profile -a 对全部应用重编译，启动更快；耗时长、占空间，可用 --reset 还原为默认编译状态",
        "perf_item_storage_trim_cached_packages" to "按包名清理编译缓存",
        "perf_item_storage_trim_cached_packages_desc" to "cmd package trim-caches 清理不再使用的编译产物与缓存目录并回读 /data 空间；清理后部分应用首次启动会略慢，系统会自动重建。此子命令在部分 ROM 上不存在",
        "perf_item_storage_drop_old_logs" to "清理日志与崩溃现场",
        "perf_item_storage_drop_old_logs_desc" to "清空 logcat 缓冲区并删除 /data/anr、/data/tombstones、/data/system/dropbox 里的历史记录，释放空间并回读剩余条数",
        "perf_item_render_animator_scale_half" to "动画缩放调至 0.5x",
        "perf_item_render_animator_scale_half_desc" to "把 window/transition/animator 三个全局缩放一起改为 0.5，交互响应更快且观感自然；可一键恢复为 1.0，执行后回读三个值",
        "perf_item_render_animator_scale_off" to "关闭全部动画",
        "perf_item_render_animator_scale_off_desc" to "把三个动画缩放改为 0，操作最快；画面会显得生硬，可一键恢复为 1.0。执行后回读三个值",
        "perf_item_render_force_gpu" to "强制 GPU 渲染并切换 skiagl",
        "perf_item_render_force_gpu_desc" to "写入 force_gpu_rendering=1 并把 debug.hwui.renderer 设为 skiagl，减轻 CPU 绘制负担；部分机型可能出现界面撕裂或闪烁，可恢复。回读开关与渲染器",
        "perf_item_net_wifi_scan_always_off" to "关闭始终允许 Wi-Fi 扫描",
        "perf_item_net_wifi_scan_always_off_desc" to "写入 wifi_scan_always_enabled=0 与 wifi_scan_throttle_enabled=0，减少熄屏期间的扫描唤醒并放宽扫描限速；代价是定位与网络感知略慢，可恢复。回读两个开关",
        "perf_item_net_mobile_data_always_off" to "关闭移动数据始终保持",
        "perf_item_net_mobile_data_always_off_desc" to "写入 mobile_data_always_on=0，避免 Wi-Fi 断开时移动数据长期常驻带来的额外唤醒；可恢复为 1，执行后回读开关",
        "perf_item_net_tcp_receive_window" to "调大 TCP 初始接收窗口",
        "perf_item_net_tcp_receive_window_desc" to "setprop net.tcp.default_init_rwnd 60，提高高延迟网络下的单流吞吐；该属性在部分内核上已不生效，回读为空即代表本机不支持，需要 Root。回读 rwnd 与缓冲区配置",
