        "hw_group_bg" to "Background and autostart",
        "hw_group_mem" to "Memory and cache",
        "hw_group_gpu" to "Rendering and GPU",
        "hw_group_power" to "Performance mode and thermal",
        "hw_group_storage" to "Storage and compilation",
        "hw_group_net" to "Network and standby",
        "hw_group_sys" to "System level (deep)",
        "hw_m_bg_kill_all" to "Kill all background processes",
        "hw_m_bg_kill_all_principle" to "Calls ActivityManagerService.killAllBackgroundProcesses. Only cached background processes are killed; foreground apps and this app are untouched.",
        "hw_m_bg_kill_all_gain" to "Immediately reclaims memory held by cached processes.",
        "hw_m_bg_disable_ota" to "Disable the OTA update service",
        "hw_m_bg_disable_ota_principle" to "com.huawei.android.hwouc performs OTA checks, downloads and package verification with periodic network wakeups. Once disabled, updates are no longer checked and the update entry stops working until re-enabled.",
        "hw_m_bg_disable_ota_gain" to "Removes the CPU, network and storage cost of periodic update checks.",
        "hw_m_bg_disable_stats" to "Disable Huawei telemetry reporting",
        "hw_m_bg_disable_stats_principle" to "com.huawei.bd collects and uploads user-experience telemetry and stays resident, causing log writes and network reporting. The package name and its exact role can differ between ROMs; verify it on your device first.",
        "hw_m_bg_disable_stats_gain" to "Cuts background log writes and reporting wakeups without affecting system features.",
        "hw_m_bg_autostart_page" to "Open Huawei app launch manager",
        "hw_m_bg_autostart_page_principle" to "Autostart is controlled by Huawei's system manager, which exposes no public shell write interface. This item only opens the launch-manager screen with am start; nothing is changed silently.",
        "hw_m_bg_autostart_page_gain" to "On Huawei devices, turning autostart off by hand is the most effective way to cut background wakeups.",
        "hw_m_mem_trim_caches" to "Trim all app caches",
        "hw_m_mem_trim_caches_principle" to "pm trim-caches asks PackageManager to tell every app to trim its own cache down to the requested free space. App data is not deleted.",
        "hw_m_mem_trim_caches_gain" to "Frees storage and relieves storage-bandwidth and memory pressure from caches.",
        "hw_m_mem_drop_caches" to "Drop kernel page cache",
        "hw_m_mem_drop_caches_principle" to "Writing 3 to /proc/sys/vm/drop_caches makes the kernel drop pagecache, dentries and inodes. sync must run first, otherwise dirty pages are written back and cause extra I/O.",
        "hw_m_mem_drop_caches_gain" to "Hands memory held by file cache back to the system at once.",
        "hw_m_mem_compact_memory" to "Trigger memory compaction",
        "hw_m_mem_compact_memory_principle" to "Writing 1 to /proc/sys/vm/compact_memory makes the kernel compact memory once, merging movable pages into contiguous blocks.",
        "hw_m_mem_compact_memory_gain" to "Improves the chance of large contiguous allocations and reduces allocation-latency jitter.",
        "hw_m_mem_lmk_tune" to "Adjust low-memory kill thresholds",
        "hw_m_mem_lmk_tune_principle" to "Rewrites /sys/module/lowmemorykiller/parameters/minfree (unit: 4KB pages) to low values so the system keeps more background processes. The original value is saved to /data/local/tmp/hw_lmk_backup. On Android 11+ most devices use userspace lmkd and the node may be absent.",
        "hw_m_mem_lmk_tune_gain" to "More background apps stay resident, so switching back avoids cold starts; too low a threshold increases reclaim thrashing.",
        "hw_m_mem_zram_off" to "Disable ZRAM swap",
        "hw_m_mem_zram_off_principle" to "swapoff /dev/block/zram0 stops compressed swap so the CPU no longer spends time compressing and decompressing pages.",
        "hw_m_mem_zram_off_gain" to "Only helps when physical RAM is plentiful and stutter comes from swap thrashing; low-RAM devices get slower.",
        "hw_m_gpu_anim_scale" to "Halve animation durations",
        "hw_m_gpu_anim_scale_principle" to "Rewrites the global settings window_animation_scale, transition_animation_scale and animator_duration_scale; WindowManager and Choreographer then shorten animations accordingly.",
        "hw_m_gpu_anim_scale_gain" to "Cuts transition waiting time in half for snappier response; the real frame rate is unchanged.",
        "hw_m_gpu_skiagl" to "Force HWUI onto SkiaGL",
        "hw_m_gpu_skiagl_principle" to "debug.hwui.renderer=skiagl makes HWUI use Skia's GPU backend. Android 12+ already defaults to SkiaGL, so this only matters on EMUI 10/11 (Android 10/11).",
        "hw_m_gpu_skiagl_gain" to "Reduces renderer pipeline switching on older EMUI builds that default to OpenGL.",
        "hw_m_gpu_render_scale" to "Lower the render resolution",
        "hw_m_gpu_render_scale_principle" to "wm size sets the logical resolution to 85% of the physical one (rounded to a multiple of 4) and SurfaceFlinger scales the output; the GPU fills about 28% fewer pixels per frame. The target is computed from the real physical size at runtime.",
        "hw_m_gpu_render_scale_gain" to "Clearly lowers GPU load and power draw, at the cost of a softer image and occasional layout issues.",
        "hw_m_gpu_sf_latch" to "Allow unsignaled frame latching",
        "hw_m_gpu_sf_latch_principle" to "debug.sf.latch_unsignaled=1 removes SurfaceFlinger's synchronized wait on the frame buffer and shortens pipeline latency by about one frame.",
        "hw_m_gpu_sf_latch_gain" to "Lowers touch-to-display latency; a few apps may show tearing.",
        "hw_m_power_mode_on" to "Turn on Huawei performance mode",
        "hw_m_power_mode_on_principle" to "Writes hw_power_mode=1 and hw_performance_mode=1 to Settings.Global / Secure, asking Huawei's power manager to switch to the performance profile. Key names differ between EMUI and HarmonyOS versions, so verify first.",
        "hw_m_power_mode_on_gain" to "Loosens CPU and GPU frequency and scheduling limits, reducing dropped frames under load.",
        "hw_m_power_saver_off" to "Leave battery saver",
        "hw_m_power_saver_off_principle" to "Sets low_power and low_power_sticky in Settings.Global to 0; PowerManagerService then leaves battery saver.",
        "hw_m_power_saver_off_gain" to "Removes battery saver's limits on CPU frequency, background sync and brightness.",
        "hw_m_power_fixed_perf" to "Fixed performance mode",
        "hw_m_power_fixed_perf_principle" to "cmd power set-fixed-performance-mode-enabled true keeps PowerManagerService in a fixed performance profile while the screen is on. This subcommand requires Android 11 or newer.",
        "hw_m_power_fixed_perf_gain" to "Stable clocks under load with fewer throttle-induced stutters; heat and battery drain rise clearly.",
        "hw_m_power_gov_performance" to "Force CPU governor to performance",
        "hw_m_power_gov_performance_principle" to "Writes performance to each core's /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor, skipping frequency sampling and holding maximum clocks. Original values are backed up to /data/local/tmp/hw_gov_backup and restored per core.",
        "hw_m_power_gov_performance_gain" to "Fastest frequency response and maximum sustained performance; idle also stays at high clocks, so heat and drain rise sharply.",
        "hw_m_power_thermal_off" to "Disable kernel thermal control",
        "hw_m_power_thermal_off_principle" to "Writes disabled to /sys/class/thermal/thermal_zone*/mode to stop kernel thermal throttling; originals are saved to /data/local/tmp/hw_thermal_backup. Huawei's own thermal service may bypass these nodes, so trust the verify output.",
        "hw_m_power_thermal_off_gain" to "No throttling at high temperature, higher short-burst performance; there is a real overheating and hardware-damage risk.",
        "hw_m_storage_bg_dexopt" to "Run background dexopt now",
        "hw_m_storage_bg_dexopt_principle" to "cmd package bg-dexopt-job makes PackageManager run the background dexopt pass immediately, compiling apps from baseline / profile instead of waiting for the nightly idle window.",
        "hw_m_storage_bg_dexopt_gain" to "Faster cold starts and first frames; CPU usage is high while it runs and the time grows with the app count.",
        "hw_m_storage_compile_all" to "Compile everything with speed-profile",
        "hw_m_storage_compile_all_principle" to "cmd package compile -m speed-profile -a AOT-compiles every installed app using its profile, writing oat files. The rollback --reset clears the output and returns to interpreter plus JIT.",
        "hw_m_storage_compile_all_gain" to "The most visible startup-speed gain; it can take over ten minutes and uses extra storage.",
        "hw_m_storage_fstrim" to "Manually TRIM /data",
        "hw_m_storage_fstrim_principle" to "Send trim requests for deleted blocks to the flash controller, easing write amplification after long use.",
        "hw_m_storage_fstrim_gain" to "Restores write performance of erased blocks; the command is slow because the controller finishes the work in the background.",
        "hw_m_storage_clear_logs" to "Clear crash logs and logcat",
        "hw_m_storage_clear_logs_principle" to "Deletes historical logs under /data/tombstones, /data/system/dropbox and /data/anr and clears the logcat buffer, cutting log-write I/O.",
        "hw_m_storage_clear_logs_gain" to "Frees storage and cuts log writes; the cost is losing crash evidence. Irreversible.",
        "hw_m_net_wifi_scan_off" to "Turn off always-on Wi-Fi scanning",
        "hw_m_net_wifi_scan_off_principle" to "Sets wifi_scan_always_enabled to 0, stopping scans even while Wi-Fi is off, which reduces idle wakeups and radio time.",
        "hw_m_net_wifi_scan_off_gain" to "Fewer idle wakeups and lower drain; scan-based location accuracy drops.",
        "hw_m_net_mobile_always_on_off" to "Turn off always-on mobile data",
        "hw_m_net_mobile_always_on_off_principle" to "Sets mobile_data_always_on to 0 so the mobile data link is not kept alive while on Wi-Fi.",
        "hw_m_net_mobile_always_on_off_gain" to "Cuts the power and signalling cost of keeping the mobile data link up.",
        "hw_m_net_wifi_low_latency" to "Enable Wi-Fi low-latency mode",
        "hw_m_net_wifi_low_latency_principle" to "cmd wifi force-low-latency-mode enabled stops the Wi-Fi driver's power-save polling and keeps traffic low-latency. Requires Android 11+ and driver support.",
        "hw_m_net_wifi_low_latency_gain" to "Lowers network jitter for games and realtime calls; slightly higher battery drain.",
        "hw_m_net_tcp_rwnd" to "Raise the TCP initial receive window",
        "hw_m_net_tcp_rwnd_principle" to "net.tcp.default_init_rwnd is the initial receive window Android's network stack reads (in MSS units); the default is 10 and this item sets it to 60. The property is empty until it is explicitly set.",
        "hw_m_net_tcp_rwnd_gain" to "Reaches available bandwidth faster on high-latency links; little effect on weak or short-lived connections.",
        "hw_m_sys_disable_hwaps" to "Disable Huawei app-acceleration service",
        "hw_m_sys_disable_hwaps_principle" to "com.huawei.android.hwaps is Huawei's app acceleration / preload service, which predicts usage and loads apps early. Disabling it removes preloading, lowering background I/O and memory use, but it may also hurt cold-start behaviour.",
        "hw_m_sys_disable_hwaps_gain" to "Cuts background I/O and resident memory; whether it is faster depends on model and ROM.",
        "hw_m_sys_disable_push" to "Disable Huawei push service",
        "hw_m_sys_disable_push_principle" to "com.huawei.android.pushagent keeps the Huawei push channel alive and dispatches messages. Once disabled, every app that relies on Huawei push stops receiving offline messages.",
        "hw_m_sys_disable_push_gain" to "Cuts one persistent connection's wakeups, memory and drain; the cost is losing all Huawei push notifications.",
        "hw_m_sys_io_scheduler" to "Set block scheduler to none",
        "hw_m_sys_io_scheduler_principle" to "Writes none to /sys/block/*/queue/scheduler, removing the scheduler's requeue overhead; UFS / NVMe multi-queue devices usually already use none. Originals are saved to /data/local/tmp/hw_io_backup.",
        "hw_m_sys_io_scheduler_gain" to "Lowers random I/O latency; some kernels do not support none and silently ignore the write.",
        "hw_m_sys_readahead" to "Raise block-device readahead",
        "hw_m_sys_readahead_principle" to "Sets /sys/block/*/queue/read_ahead_kb to 2048 so sequential reads prefetch more per request; originals are saved to /data/local/tmp/hw_ra_backup.",
        "hw_m_sys_readahead_gain" to "Faster sequential reads of large files; limited gain for random reads, and excessive readahead squeezes the page cache.",
        "temp_root_title" to "Temporary Root",
        "temp_root_cpu_hint" to "Pick the package that matches your SoC model; the escalation method differs per device.",
        "temp_root_vendor" to "Vendor",
        "temp_root_soc_mediatek" to "MediaTek (Dimensity)",
        "temp_root_soc_qualcomm" to "Qualcomm (Snapdragon)",
        "temp_root_package" to "Escalation package",
        "temp_root_selected" to "Selected: %1\$s",
        "temp_root_pick_zip" to "Choose package (ZIP)",
        "temp_root_perm_hint" to "The package runs its script as shell/Root. No Shizuku (ADB) or Root detected, so this will most likely fail.",
        "temp_root_flash" to "Run escalation",
        "temp_root_warn" to "Escalation is risky and can leave the device unable to boot. Back up important data first.",
        "temp_root_start" to "Start",
        "temp_root_running" to "Running…",
        "temp_root_fail_no_file" to "Failed: no package selected",
        "temp_root_fail_exception" to "Failed: execution error. Check Shizuku/Root permission and retry.",
        "temp_root_ok" to "Escalation succeeded!\n%1\$s",
        "temp_root_fail" to "Escalation failed: %1\$s\n%2\$s",
        "installed_root_modules" to "Installed modules",
        "close" to "Close",
        "size" to "Size",
        "copy" to "Copy",
        "perf_item_bg_kill_background_all" to "Kill all background processes",
        "perf_item_bg_kill_background_all_desc" to "am kill-all ends every reclaimable background process and reads Free RAM back; works with Shizuku or Root",
        "perf_item_bg_trim_all_caches" to "Trim all app caches",
        "perf_item_bg_trim_all_caches_desc" to "pm trim-caches releases all app cache space and reads back free /data space",
        "perf_item_bg_standby_bucket_rare" to "Move common apps to the RARE standby bucket",
        "perf_item_bg_standby_bucket_rare_desc" to "Runs am set-standby-bucket rare on 15 common third-party apps to cut background wakeups; notifications from them are clearly delayed, reversible to active",
        "perf_item_bg_standby_bucket_extreme" to "Move key apps to the RESTRICTED bucket",
        "perf_item_bg_standby_bucket_extreme_desc" to "Runs am set-standby-bucket restricted on 5 apps (WeChat, Taobao, Douyin and others), freezing them almost completely in background; push messages are heavily delayed or lost, reversible. Some ROMs remove this interface, so it is off by default",
        "perf_item_bg_restrict_background_appops" to "Restrict third-party background execution",
        "perf_item_bg_restrict_background_appops_desc" to "Sets appops RUN_IN_BACKGROUND / RUN_ANY_IN_BACKGROUND to deny for the first 60 third-party apps, truly cutting background residency; their notifications may be delayed, the restore command sets allow back",
        "perf_item_bg_deviceidle_whitelist_core" to "Whitelist core system components from Doze",
        "perf_item_bg_deviceidle_whitelist_core_desc" to "Adds SystemUI / phone / bluetooth / telephony provider to the deviceidle whitelist so Doze does not freeze them and cause jank; the first whitelist line is read back",
        "perf_item_bg_deviceidle_unforce" to "Exit Doze idle immediately",
        "perf_item_bg_deviceidle_unforce_desc" to "cmd deviceidle unforce makes the system leave IDLE at once and reads mState back, waking frozen background work. Not a setting, so it has no undo",
        "perf_item_bg_deviceidle_disable" to "Disable Doze deep idle",
        "perf_item_bg_deviceidle_disable_desc" to "cmd deviceidle disable turns Doze deep idle off so background work is no longer frozen; standby power drain rises clearly, and some ROMs removed this subcommand after Android 12, so it is off by default",
        "perf_item_bg_oom_adj_policy" to "Tune the OOM kill policy",
        "perf_item_bg_oom_adj_policy_desc" to "Writes /proc/sys/vm/oom_kill_allocating_task=0 and oom_dump_tasks=1 so the OOM killer prefers the largest consumer and dumps state, needs Root; both nodes are read back after execution",
        "perf_item_cpu_fixed_perf_mode" to "Enable fixed performance mode",
        "perf_item_cpu_fixed_perf_mode_desc" to "cmd power set-fixed-performance-mode-enabled true keeps CPU/GPU at high clocks; heat and power drain rise clearly, mFixedPerformanceMode is read back",
        "perf_item_cpu_governor_performance" to "Switch CPU governor to performance",
        "perf_item_cpu_governor_performance_desc" to "Writes scaling_governor=performance per core after backing the original governors up to /data/local/tmp; the restore command replays them, needs Root. The current cpu0 governor is read back",
        "perf_item_cpu_min_freq_boost" to "Raise CPU minimum frequency to max",
        "perf_item_cpu_min_freq_boost_desc" to "Writes scaling_min_freq from cpuinfo_max_freq to shrink downclocking room; original values are backed up per core and restorable, needs Root. cpu0 min/max frequencies are read back",
        "perf_item_cpu_schedutil_rate_limit" to "Lower the frequency ramp-up interval",
        "perf_item_cpu_schedutil_rate_limit_desc" to "Pushes rate_limit_us down to 2000 for faster frequency response; the original value is backed up and restorable, needs Root. The node path differs across kernels, so check the read-back value first",
        "perf_item_cpu_io_scheduler_none" to "Set block IO scheduler to none",
        "perf_item_cpu_io_scheduler_none_desc" to "Writes the none scheduler to sd*/mmcblk*/dm-*/vda to cut queue overhead on flash; the previous schedulers are recorded and restorable, needs Root. This path mainly applies to UFS/eMMC devices",
        "perf_item_mem_swappiness_low" to "Lower the swap tendency",
        "perf_item_mem_swappiness_low_desc" to "Writes vm.swappiness=10 and page-cluster=150 to cut page swap in/out cost on ZRAM; the original swappiness is backed up and restorable, needs Root. Both nodes are read back",
        "perf_item_power_perf_profile" to "Clear the system power-saving mode",
        "perf_item_power_perf_profile_desc" to "cmd power set-mode 0 takes the power mode out of battery saver and reads the state back; when the set-profile subcommand is missing on a ROM it reports the error honestly instead of hiding it",
        "perf_item_storage_bg_dexopt_now" to "Run background dex optimization now",
        "perf_item_storage_bg_dexopt_now_desc" to "cmd package bg-dexopt-job runs AOT compilation for not-yet-optimized apps to speed up launches; it can take minutes and warming up during the run is normal",
        "perf_item_storage_compile_speed_profile" to "Compile all packages with speed-profile",
        "perf_item_storage_compile_speed_profile_desc" to "cmd package compile -m speed-profile -a recompiles every app for faster starts; slow and space-hungry, and --reset returns packages to the default compile state",
        "perf_item_storage_trim_cached_packages" to "Trim package caches",
        "perf_item_storage_trim_cached_packages_desc" to "cmd package trim-caches drops unused compiled artifacts and cache directories and reads /data back; a few apps start slower once and the system rebuilds them. This subcommand is missing on some ROMs",
        "perf_item_storage_drop_old_logs" to "Clear logs and crash dumps",
        "perf_item_storage_drop_old_logs_desc" to "Clears the logcat buffers and deletes history in /data/anr, /data/tombstones and /data/system/dropbox, then reads back how many entries remain",
        "perf_item_render_animator_scale_half" to "Set animation scales to 0.5x",
        "perf_item_render_animator_scale_half_desc" to "Sets the window/transition/animator global scales to 0.5 together for snappier but still natural motion; one command restores 1.0, and all three values are read back",
        "perf_item_render_animator_scale_off" to "Disable all animations",
        "perf_item_render_animator_scale_off_desc" to "Sets the three animation scales to 0 for the fastest response; motion looks abrupt, and one command restores 1.0. All three values are read back",
        "perf_item_render_force_gpu" to "Force GPU rendering and use skiagl",
        "perf_item_render_force_gpu_desc" to "Writes force_gpu_rendering=1 and sets debug.hwui.renderer to skiagl to offload CPU drawing; some devices show tearing or flicker, reversible. The switch and renderer are read back",
        "perf_item_net_wifi_scan_always_off" to "Turn off always-on Wi-Fi scanning",
        "perf_item_net_wifi_scan_always_off_desc" to "Writes wifi_scan_always_enabled=0 and wifi_scan_throttle_enabled=0 to cut scan wakeups while the screen is off and to loosen scan throttling; location and network awareness get slightly slower, reversible. Both switches are read back",
        "perf_item_net_mobile_data_always_off" to "Turn off always-on mobile data",
        "perf_item_net_mobile_data_always_off_desc" to "Writes mobile_data_always_on=0 so mobile data does not stay resident and wake the radio whenever Wi-Fi drops; restorable to 1, and the switch is read back",
        "perf_item_net_tcp_receive_window" to "Raise the initial TCP receive window",
        "perf_item_net_tcp_receive_window_desc" to "setprop net.tcp.default_init_rwnd 60 raises single-stream throughput on high-latency links; the property no longer takes effect on some kernels and an empty read-back means unsupported here, needs Root. rwnd and the buffer config are read back",
