        "hw_m_bg_disable_ota_principle" to "com.huawei.android.hwouc OTA जाँच, डाउनलोड और सत्यापन करता है और समय-समय पर नेटवर्क जगाता है। बंद करने पर अपडेट जाँच बंद हो जाती है।",
        "hw_m_bg_disable_ota_gain" to "समय-समय पर अपडेट जाँच का CPU, नेटवर्क और स्टोरेज खर्च हटता है।",
        "hw_m_bg_disable_stats" to "Huawei डेटा रिपोर्टिंग बंद करें",
        "hw_m_bg_disable_stats_principle" to "com.huawei.bd उपयोगकर्ता अनुभव डेटा इकट्ठा और भेजता है और बैकग्राउंड में चलता रहता है। ROM के अनुसार पैकेज नाम और कार्य थोड़ा बदल सकता है।",
        "hw_m_bg_disable_stats_gain" to "बैकग्राउंड लॉग लेखन और रिपोर्टिंग वेकअप घटते हैं, सिस्टम फ़ीचर प्रभावित नहीं होते।",
        "hw_m_bg_autostart_page" to "Huawei ऐप लॉन्च मैनेजर खोलें",
        "hw_m_bg_autostart_page_principle" to "ऑटोस्टार्ट Huawei सिस्टम मैनेजर संभालता है, इसके लिए सार्वजनिक shell इंटरफ़ेस नहीं है। यह आइटम केवल am start से स्क्रीन खोलता है।",
        "hw_m_bg_autostart_page_gain" to "Huawei डिवाइस पर ऑटोस्टार्ट हाथ से बंद करना सबसे असरदार तरीका है।",
        "hw_m_mem_trim_caches" to "सभी ऐप कैश साफ़ करें",
        "hw_m_mem_trim_caches_principle" to "pm trim-caches PackageManager से हर ऐप को उसका कैश छोटा करने को कहता है। ऐप डेटा नहीं मिटता।",
        "hw_m_mem_trim_caches_gain" to "स्टोरेज खाली होता है और कैश का दबाव घटता है।",
        "hw_m_mem_drop_caches" to "kernel page cache खाली करें",
        "hw_m_mem_drop_caches_principle" to "/proc/sys/vm/drop_caches में 3 लिखने पर kernel pagecache, dentries और inodes छोड़ देता है। पहले sync ज़रूरी है।",
        "hw_m_mem_drop_caches_gain" to "फ़ाइल कैश की मेमोरी तुरंत सिस्टम को वापस मिलती है।",
        "hw_m_mem_compact_memory" to "मेमोरी कंपैक्शन चलाएँ",
        "hw_m_mem_compact_memory_principle" to "/proc/sys/vm/compact_memory में 1 लिखने पर kernel मेमोरी को एक बार व्यवस्थित करता है।",
        "hw_m_mem_compact_memory_gain" to "बड़े लगातार मेमोरी आवंटन की संभावना बढ़ती है और विलंब कम होता है।",
        "hw_m_mem_lmk_tune" to "लो-मेमोरी किल थ्रेशोल्ड बदलें",
        "hw_m_mem_lmk_tune_principle" to "/sys/module/lowmemorykiller/parameters/minfree (इकाई 4KB पेज) को कम मान पर सेट करता है। मूल मान /data/local/tmp/hw_lmk_backup में सुरक्षित रहता है।",
        "hw_m_mem_lmk_tune_gain" to "ज़्यादा बैकग्राउंड ऐप बने रहते हैं, वापस आने पर ठंडी शुरुआत कम होती है।",
        "hw_m_mem_zram_off" to "ZRAM स्वैप बंद करें",
        "hw_m_mem_zram_off_principle" to "swapoff /dev/block/zram0 संपीड़ित स्वैप बंद करता है, CPU समय बचाता है।",
        "hw_m_mem_zram_off_gain" to "यह केवल तब लाभ देता है जब भौतिक RAM पर्याप्त हो; कम RAM वाले डिवाइस धीमे हो जाते हैं।",
        "hw_m_gpu_anim_scale" to "एनिमेशन अवधि आधी करें",
        "hw_m_gpu_anim_scale_principle" to "तीन ग्लोबल सेटिंग बदलता है, जिससे WindowManager एनिमेशन छोटे कर देता है।",
        "hw_m_gpu_anim_scale_gain" to "स्क्रीन बदलने का इंतज़ार आधा हो जाता है; असली फ़्रेम दर नहीं बदलती।",
        "hw_m_gpu_skiagl" to "HWUI को SkiaGL पर लाएँ",
        "hw_m_gpu_skiagl_principle" to "debug.hwui.renderer=skiagl HWUI को Skia GPU बैकएंड पर ले जाता है। Android 12+ में यह पहले से डिफ़ॉल्ट है।",
        "hw_m_gpu_skiagl_gain" to "OpenGL डिफ़ॉल्ट वाले पुराने EMUI पर रेंडरिंग ओवरहेड घटता है।",
        "hw_m_gpu_render_scale" to "रेंडर रेज़ोल्यूशन घटाएँ",
        "hw_m_gpu_render_scale_principle" to "wm size लॉजिकल रेज़ोल्यूशन को भौतिक का 85% कर देता है; GPU को हर फ़्रेम में लगभग 28% कम पिक्सेल भरने पड़ते हैं।",
        "hw_m_gpu_render_scale_gain" to "GPU लोड और बिजली खपत साफ़ घटती है, पर तस्वीर थोड़ी धुंधली होती है।",
        "hw_m_gpu_sf_latch" to "असिंक्रोनस फ़्रेम लैचिंग चालू करें",
        "hw_m_gpu_sf_latch_principle" to "debug.sf.latch_unsignaled=1 SurfaceFlinger की सिंक्रोनस प्रतीक्षा हटाता है और विलंब घटाता है।",
        "hw_m_gpu_sf_latch_gain" to "टच से डिस्प्ले तक विलंब घटता है; कुछ ऐप में टियरिंग हो सकती है।",
        "hw_m_power_mode_on" to "Huawei परफ़ॉर्मेंस मोड चालू करें",
        "hw_m_power_mode_on_principle" to "Settings.Global / Secure में hw_power_mode=1 और hw_performance_mode=1 लिखता है। कुंजी नाम हर संस्करण में एक जैसे नहीं हैं, पहले सत्यापन करें।",
        "hw_m_power_mode_on_gain" to "CPU / GPU फ़्रीक्वेंसी सीमाएँ ढीली होती हैं, भारी लोड में फ़्रेम कम गिरते हैं।",
        "hw_m_power_saver_off" to "बैटरी सेवर बंद करें",
        "hw_m_power_saver_off_principle" to "Settings.Global के low_power और low_power_sticky को 0 करता है, PowerManagerService बैटरी सेवर छोड़ देता है।",
        "hw_m_power_saver_off_gain" to "CPU फ़्रीक्वेंसी, बैकग्राउंड सिंक और ब्राइटनेस पर से सीमाएँ हटती हैं।",
        "hw_m_power_fixed_perf" to "फ़िक्स्ड परफ़ॉर्मेंस मोड",
        "hw_m_power_fixed_perf_principle" to "यह कमांड स्क्रीन चालू रहने तक प्रदर्शन प्रोफ़ाइल स्थिर रखता है। Android 11 या नया चाहिए।",
        "hw_m_power_fixed_perf_gain" to "लोड में फ़्रीक्वेंसी स्थिर रहती है; गर्मी और बैटरी खपत बढ़ती है।",
        "hw_m_power_gov_performance" to "CPU गवर्नर performance करें",
        "hw_m_power_gov_performance_principle" to "हर कोर के scaling_governor में performance लिखता है। मूल मान /data/local/tmp/hw_gov_backup में सुरक्षित रहते हैं।",
        "hw_m_power_gov_performance_gain" to "सबसे तेज़ फ़्रीक्वेंसी प्रतिक्रिया; खाली समय में भी उच्च क्लॉक, गर्मी और खपत बढ़ती है।",
        "hw_m_power_thermal_off" to "kernel थर्मल नियंत्रण बंद करें",
        "hw_m_power_thermal_off_principle" to "/sys/class/thermal/thermal_zone*/mode में disabled लिखता है। Huawei की थर्मल सेवा इसे बायपास कर सकती है।",
        "hw_m_power_thermal_off_gain" to "उच्च तापमान पर थ्रॉटलिंग नहीं होती; ज़्यादा गर्मी और हार्डवेयर नुकसान का जोखिम है।",
        "hw_m_storage_bg_dexopt" to "बैकग्राउंड dexopt अभी चलाएँ",
        "hw_m_storage_bg_dexopt_principle" to "cmd package bg-dexopt-job PackageManager से तुरंत बैकग्राउंड dexopt चलवाता है।",
        "hw_m_storage_bg_dexopt_gain" to "ऐप की ठंडी शुरुआत तेज़ होती है; चलने के दौरान CPU ज़्यादा लगता है।",
        "hw_m_storage_compile_all" to "सब कुछ speed-profile से कंपाइल करें",
        "hw_m_storage_compile_all_principle" to "cmd package compile -m speed-profile -a सभी ऐप को AOT कंपाइल करता है। वापसी --reset इसे हटा देता है।",
        "hw_m_storage_compile_all_gain" to "शुरुआत की गति में सबसे साफ़ सुधार; दस मिनट से ज़्यादा लग सकते हैं और स्टोरेज लगता है।",
        "hw_m_storage_fstrim" to "/data पर TRIM चलाएँ",
        "hw_m_storage_fstrim_principle" to "मिटाए गए ब्लॉक की trim रिक्वेस्ट फ़्लैश कंट्रोलर को भेजता है।",
        "hw_m_storage_fstrim_gain" to "मिटाए ब्लॉक की लेखन गति लौटती है; कमांड धीमा चलता है।",
        "hw_m_storage_clear_logs" to "क्रैश लॉग और logcat साफ़ करें",
        "hw_m_storage_clear_logs_principle" to "/data/tombstones, /data/system/dropbox, /data/anr के पुराने लॉग मिटाता है और logcat बफ़र साफ़ करता है।",
        "hw_m_storage_clear_logs_gain" to "स्टोरेज बचता है पर क्रैश सबूत मिट जाते हैं। अपरिवर्तनीय।",
        "hw_m_net_wifi_scan_off" to "हमेशा WLAN स्कैन बंद करें",
        "hw_m_net_wifi_scan_off_principle" to "wifi_scan_always_enabled=0 करता है, जिससे स्टैंडबाय में स्कैन बंद हो जाता है।",
        "hw_m_net_wifi_scan_off_gain" to "स्टैंडबाय वेकअप और खपत घटती है; स्कैन आधारित लोकेशन कम सटीक होती है।",
        "hw_m_net_mobile_always_on_off" to "मोबाइल डेटा हमेशा चालू बंद करें",
        "hw_m_net_mobile_always_on_off_principle" to "WLAN पर रहते हुए भी मोबाइल डेटा लिंक बनाए रखने की सेटिंग बंद करता है।",
        "hw_m_net_mobile_always_on_off_gain" to "मोबाइल डेटा लिंक बनाए रखने की बैटरी और सिग्नलिंग लागत घटती है।",
        "hw_m_net_wifi_low_latency" to "WLAN लो-लेटेंसी मोड चालू करें",
        "hw_m_net_wifi_low_latency_principle" to "यह कमांड WLAN ड्राइवर का पावर-सेव पोलिंग बंद करता है। Android 11+ और ड्राइवर समर्थन चाहिए।",
        "hw_m_net_wifi_low_latency_gain" to "गेम और रीयलटाइम कॉल में नेटवर्क जिटर घटता है; बैटरी थोड़ी ज़्यादा लगती है।",
        "hw_m_net_tcp_rwnd" to "TCP प्रारंभिक रिसीव विंडो बढ़ाएँ",
        "hw_m_net_tcp_rwnd_principle" to "net.tcp.default_init_rwnd प्रारंभिक रिसीव विंडो है (MSS इकाई में), डिफ़ॉल्ट 10; यह 60 करता है।",
        "hw_m_net_tcp_rwnd_gain" to "ज़्यादा विलंब वाले नेटवर्क पर बैंडविड्थ जल्दी मिलती है; कमज़ोर नेटवर्क में लाभ सीमित है।",
        "hw_m_sys_disable_hwaps" to "Huawei ऐप-त्वरण सेवा बंद करें",
        "hw_m_sys_disable_hwaps_principle" to "com.huawei.android.hwaps ऐप प्रीलोड सेवा है। बंद करने पर बैकग्राउंड I/O घटता है, पर ठंडी शुरुआत प्रभावित हो सकती है।",
        "hw_m_sys_disable_hwaps_gain" to "बैकग्राउंड I/O और मेमोरी घटती है; असर मॉडल और ROM पर निर्भर है।",
        "hw_m_sys_disable_push" to "Huawei पुश सेवा बंद करें",
        "hw_m_sys_disable_push_principle" to "com.huawei.android.pushagent Huawei पुश चैनल चलाता है। बंद करने पर सभी संबंधित ऐप को ऑफ़लाइन संदेश नहीं मिलेंगे।",
        "hw_m_sys_disable_push_gain" to "एक स्थायी कनेक्शन के वेकअप और खपत घटते हैं; सभी Huawei पुश सूचनाएँ मिलना बंद हो जाती हैं।",
        "hw_m_sys_io_scheduler" to "ब्लॉक शेड्यूलर none करें",
        "hw_m_sys_io_scheduler_principle" to "/sys/block/*/queue/scheduler में none लिखता है। मूल मान /data/local/tmp/hw_io_backup में रहता है।",
        "hw_m_sys_io_scheduler_gain" to "रैंडम I/O विलंब घटता है; कुछ kernel none समर्थित नहीं करते।",
        "hw_m_sys_readahead" to "ब्लॉक डिवाइस रीडअहेड बढ़ाएँ",
        "hw_m_sys_readahead_principle" to "/sys/block/*/queue/read_ahead_kb को 2048 करता है; मूल मान /data/local/tmp/hw_ra_backup में रहता है।",
        "hw_m_sys_readahead_gain" to "बड़ी फ़ाइलों की क्रमिक पढ़ाई तेज़ होती है; रैंडम पढ़ाई में लाभ कम है।",
        "temp_root_title" to "अस्थायी Root",
        "temp_root_cpu_hint" to "अपने SoC मॉडल से मेल खाता पैकेज चुनें; हर डिवाइस की विधि अलग है।",
        "temp_root_vendor" to "निर्माता",
        "temp_root_soc_mediatek" to "MediaTek (Dimensity)",
        "temp_root_soc_qualcomm" to "Qualcomm (Snapdragon)",
        "temp_root_package" to "एस्केलेशन पैकेज",
        "temp_root_selected" to "चुना गया: %1\$s",
        "temp_root_pick_zip" to "पैकेज चुनें (ZIP)",
        "temp_root_perm_hint" to "पैकेज स्क्रिप्ट shell/Root के रूप में चलाता है। Shizuku (ADB) या Root नहीं मिला, इसलिए यह संभवतः विफल होगा।",
        "temp_root_flash" to "एस्केलेशन चलाएँ",
        "temp_root_warn" to "एस्केलेशन जोखिम भरा है और डिवाइस बूट न हो; पहले डेटा का बैकअप लें।",
        "temp_root_start" to "शुरू करें",
        "temp_root_running" to "चल रहा है…",
        "temp_root_fail_no_file" to "विफल: कोई पैकेज नहीं चुना",
        "temp_root_fail_exception" to "विफल: निष्पादन त्रुटि। Shizuku/Root अनुमति जाँचकर पुनः प्रयास करें।",
        "temp_root_ok" to "एस्केलेशन सफल!\n%1\$s",
        "temp_root_fail" to "एस्केलेशन विफल: %1\$s\n%2\$s",
        "installed_root_modules" to "इंस्टॉल मॉड्यूल",
        "close" to "बंद करें",
        "size" to "आकार",
        "copy" to "कॉपी करें",
        "perf_item_bg_kill_background_all" to "सभी बैकग्राउंड प्रक्रियाएँ बंद करें",
        "perf_item_bg_kill_background_all_desc" to "am kill-all सभी रिक्लेम करने योग्य बैकग्राउंड प्रक्रियाएँ बंद करता है और Free RAM पढ़ता है; Shizuku या Root से काम करता है",
        "perf_item_bg_trim_all_caches" to "सभी ऐप कैश साफ़ करें",
        "perf_item_bg_trim_all_caches_desc" to "pm trim-caches सभी ऐप कैश मुक्त करता है और /data की खाली जगह दिखाता है",
        "perf_item_bg_standby_bucket_rare" to "सामान्य ऐप्स को RARE स्टैंडबाय बकेट में डालें",
        "perf_item_bg_standby_bucket_rare_desc" to "15 सामान्य थर्ड-पार्टी ऐप्स पर am set-standby-bucket rare चलाता है, बैकग्राउंड जागृति घटती है; इनकी सूचनाएँ देर से आएँगी, active पर वापसी संभव",
        "perf_item_bg_standby_bucket_extreme" to "प्रमुख ऐप्स को RESTRICTED बकेट में डालें",
        "perf_item_bg_standby_bucket_extreme_desc" to "5 ऐप्स पर am set-standby-bucket restricted चलाता है, बैकग्राउंड लगभग पूरी तरह फ्रीज़; पुश संदेश बहुत देर से आएँगे या खो सकते हैं, वापसी संभव। कुछ ROM में यह इंटरफ़ेस नहीं होता, इसलिए डिफ़ॉल्ट बंद",
        "perf_item_bg_restrict_background_appops" to "थर्ड-पार्टी ऐप्स का बैकग्राउंड चलना रोकें",
        "perf_item_bg_restrict_background_appops_desc" to "पहले 60 थर्ड-पार्टी ऐप्स के लिए appops RUN_IN_BACKGROUND / RUN_ANY_IN_BACKGROUND deny करता है, बैकग्राउंड वास्तव में बंद; सूचनाएँ देर से आ सकती हैं, रीस्टोर कमांड allow कर देता है",
        "perf_item_bg_deviceidle_whitelist_core" to "मुख्य सिस्टम घटकों को Doze व्हाइटलिस्ट में डालें",
        "perf_item_bg_deviceidle_whitelist_core_desc" to "SystemUI / फ़ोन / ब्लूटूथ / टेलीफ़ोनी प्रोवाइडर को deviceidle व्हाइटलिस्ट में जोड़ता है ताकि Doze उन्हें फ्रीज़ न करे; व्हाइटलिस्ट की पहली पंक्ति वापस पढ़ी जाती है",
        "perf_item_bg_deviceidle_unforce" to "Doze आइडल से तुरंत बाहर निकलें",
        "perf_item_bg_deviceidle_unforce_desc" to "cmd deviceidle unforce सिस्टम को तुरंत IDLE से बाहर लाता है और mState पढ़ता है, फ्रीज़्ड बैकग्राउंड काम जागते हैं। यह सेटिंग नहीं, एक बार का कार्य है",
        "perf_item_bg_deviceidle_disable" to "Doze डीप आइडल बंद करें",
        "perf_item_bg_deviceidle_disable_desc" to "cmd deviceidle disable Doze डीप आइडल बंद करता है, बैकग्राउंड फ्रीज़ नहीं होता; स्टैंडबाय बैटरी खपत बढ़ती है, और Android 12 के बाद कुछ ROM में यह सबकमांड हटा दिया गया, इसलिए डिफ़ॉल्ट बंद",
        "perf_item_bg_oom_adj_policy" to "OOM किल नीति बदलें",
        "perf_item_bg_oom_adj_policy_desc" to "/proc/sys/vm/oom_kill_allocating_task=0 और oom_dump_tasks=1 लिखता है ताकि OOM किलर सबसे बड़े उपभोक्ता को चुने और स्थिति डंप करे, Root चाहिए; दोनों नोड वापस पढ़े जाते हैं",
        "perf_item_cpu_fixed_perf_mode" to "फिक्स्ड परफ़ॉर्मेंस मोड चालू करें",
        "perf_item_cpu_fixed_perf_mode_desc" to "cmd power set-fixed-performance-mode-enabled true CPU/GPU को लंबे समय तक उच्च क्लॉक पर रखता है; गर्मी और बिजली खपत बढ़ती है, mFixedPerformanceMode वापस पढ़ा जाता है",
        "perf_item_cpu_governor_performance" to "CPU गवर्नर performance पर सेट करें",
        "perf_item_cpu_governor_performance_desc" to "मूल गवर्नर को /data/local/tmp में बैकअप लेकर हर कोर पर scaling_governor=performance लिखता है; रीस्टोर कमांड उन्हें वापस लगाता है, Root चाहिए। cpu0 का मौजूदा गवर्नर वापस पढ़ा जाता है",
        "perf_item_cpu_min_freq_boost" to "CPU की न्यूनतम फ़्रीक्वेंसी अधिकतम तक बढ़ाएँ",
        "perf_item_cpu_min_freq_boost_desc" to "cpuinfo_max_freq से scaling_min_freq लिखता है ताकि डाउनक्लॉकिंग कम हो; मूल मान हर कोर के लिए बैकअप और रीस्टोर होते हैं, Root चाहिए। cpu0 की min/max फ़्रीक्वेंसी वापस पढ़ी जाती है",
        "perf_item_cpu_schedutil_rate_limit" to "फ़्रीक्वेंसी रैंप-अप अंतराल घटाएँ",
        "perf_item_cpu_schedutil_rate_limit_desc" to "तेज़ फ़्रीक्वेंसी प्रतिक्रिया के लिए rate_limit_us को 2000 करता है; मूल मान बैकअप और रीस्टोर होता है, Root चाहिए। नोड का पथ हर कर्नेल में अलग हो सकता है, पहले रीड-बैक देखें",
        "perf_item_cpu_io_scheduler_none" to "ब्लॉक IO शेड्यूलर none करें",
        "perf_item_cpu_io_scheduler_none_desc" to "sd*/mmcblk*/dm-*/vda पर none शेड्यूलर लिखता है ताकि फ़्लैश पर कतार ओवरहेड घटे; पिछले शेड्यूलर दर्ज और रीस्टोर होते हैं, Root चाहिए। यह मुख्यतः UFS/eMMC डिवाइस पर लागू होता है",
        "perf_item_mem_swappiness_low" to "स्वैप की प्रवृत्ति घटाएँ",
        "perf_item_mem_swappiness_low_desc" to "ZRAM पर पेज स्वैप की लागत घटाने के लिए vm.swappiness=10 और page-cluster=150 लिखता है; मूल swappiness बैकअप और रीस्टोर होता है, Root चाहिए। दोनों नोड वापस पढ़े जाते हैं",
        "perf_item_power_perf_profile" to "सिस्टम पावर-सेविंग मोड हटाएँ",
        "perf_item_power_perf_profile_desc" to "cmd power set-mode 0 पावर मोड को बैटरी सेवर से बाहर लाता है और स्थिति पढ़ता है; किसी ROM में set-profile न हो तो त्रुटि साफ़ बताई जाती है",
        "perf_item_storage_bg_dexopt_now" to "अभी बैकग्राउंड डेक्स ऑप्टिमाइज़ेशन चलाएँ",
        "perf_item_storage_bg_dexopt_now_desc" to "cmd package bg-dexopt-job बिना ऑप्टिमाइज़्ड ऐप्स की AOT कंपाइल करता है जिससे ऐप तेज़ खुलते हैं; कुछ मिनट लग सकते हैं और चलते समय गर्मी सामान्य है",
        "perf_item_storage_compile_speed_profile" to "सभी पैकेज speed-profile से कंपाइल करें",
        "perf_item_storage_compile_speed_profile_desc" to "cmd package compile -m speed-profile -a हर ऐप को तेज़ शुरुआत के लिए दोबारा कंपाइल करता है; धीमा और जगह लेने वाला, --reset डिफ़ॉल्ट स्थिति में लौटा देता है",
        "perf_item_storage_trim_cached_packages" to "पैकेज कैश ट्रिम करें",
        "perf_item_storage_trim_cached_packages_desc" to "cmd package trim-caches बिना इस्तेमाल के कंपाइल आर्टिफ़ैक्ट और कैश हटाता है और /data पढ़ता है; कुछ ऐप पहली बार धीमे खुलेंगे और सिस्टम उन्हें दोबारा बनाएगा। कुछ ROM में यह सबकमांड नहीं है",
        "perf_item_storage_drop_old_logs" to "लॉग और क्रैश डंप साफ़ करें",
        "perf_item_storage_drop_old_logs_desc" to "logcat बफ़र साफ़ करता है और /data/anr, /data/tombstones, /data/system/dropbox का इतिहास हटाता है, फिर बची प्रविष्टियाँ पढ़ता है",
        "perf_item_render_animator_scale_half" to "एनिमेशन स्केल 0.5x करें",
        "perf_item_render_animator_scale_half_desc" to "विंडो/ट्रांज़िशन/एनिमेटर तीनों ग्लोबल स्केल एक साथ 0.5 करता है, प्रतिक्रिया तेज़ और दिखने में सहज; एक कमांड से 1.0 वापस, तीनों मान वापस पढ़े जाते हैं",
        "perf_item_render_animator_scale_off" to "सभी एनिमेशन बंद करें",
        "perf_item_render_animator_scale_off_desc" to "तीनों एनिमेशन स्केल 0 करता है, प्रतिक्रिया सबसे तेज़; चाल कठोर लगेगी, एक कमांड से 1.0 वापस। तीनों मान वापस पढ़े जाते हैं",
