        "perf_item_render_force_gpu_desc" to "CPU ड्रॉइंग का भार घटाने के लिए force_gpu_rendering=1 लिखता है और debug.hwui.renderer को skiagl करता है; कुछ डिवाइस पर टियरिंग या झिलमिलाहट हो सकती है, वापसी संभव। स्विच और रेंडरर वापस पढ़े जाते हैं",
        "perf_item_net_wifi_scan_always_off" to "हमेशा Wi-Fi स्कैन बंद करें",
        "perf_item_net_wifi_scan_always_off_desc" to "स्क्रीन बंद रहते स्कैन जागृति घटाने और स्कैन थ्रॉटलिंग ढीली करने के लिए wifi_scan_always_enabled=0 और wifi_scan_throttle_enabled=0 लिखता है; लोकेशन और नेटवर्क पहचान थोड़ी धीमी, वापसी संभव। दोनों स्विच वापस पढ़े जाते हैं",
