        "perf_item_net_mobile_data_always_off_desc" to "mobile_data_always_on=0 लिखता है ताकि Wi-Fi टूटने पर मोबाइल डेटा रेडियो को जगाए न रखे; 1 पर वापसी संभव, स्विच वापस पढ़ा जाता है",
