        "perf_item_net_tcp_receive_window_desc" to "setprop net.tcp.default_init_rwnd 60 उच्च लेटेंसी लिंक पर सिंगल-स्ट्रीम थ्रूपुट बढ़ाता है; कुछ कर्नेल पर यह प्रॉपर्टी असरदार नहीं रहती और खाली रीड-बैक का अर्थ है यहाँ असमर्थित, Root चाहिए। rwnd और बफ़र कॉन्फ़िग वापस पढ़े जाते हैं",
